package com.cryptoaipro.monitor

/**
 * Curated Persian crypto/futures knowledge base.
 * This is a compact, explainable reference library, not a claim of one million verified facts.
 * Entries teach concepts and warn where exchange rules or market conditions can change.
 */
internal object WolfCryptoKnowledgeBase {
    private data class Entry(val title: String, val keys: List<String>, val body: String)

    private fun norm(s: String) = s.lowercase()
        .replace('ي','ی').replace('ك','ک')
        .replace(Regex("[\\u064B-\\u065F\\u0670]"), "")
        .replace(Regex("[^\\p{L}\\p{N}]+"), " ").trim()

    private val entries = listOf(
        Entry("فیوچرز و قرارداد دائمی", listOf("فیوچرز","قرارداد آتی","perpetual","پرپچوال"), "فیوچرز قراردادی است که ارزش آن از دارایی پایه مشتق می‌شود. قرارداد دائمی تاریخ سررسید ندارد و معمولاً با مکانیزم Funding به قیمت شاخص نزدیک نگه داشته می‌شود. قیمت قرارداد ممکن است با قیمت لحظه‌ای تفاوت داشته باشد."),
        Entry("لانگ و شورت", listOf("لانگ","long","خرید","شورت","short","فروش"), "لانگ از افزایش قیمت سود می‌گیرد و شورت از کاهش قیمت. هر دو جهت در فیوچرز می‌توانند زیان سریع ایجاد کنند. جهت سیگنال به‌تنهایی کافی نیست؛ نقطه ابطال، اندازه ریسک، نقدشوندگی و هزینه‌ها باید بررسی شوند."),
        Entry("اهرم", listOf("اهرم","لوریج","leverage"), "اهرم اندازه مواجهه اسمی را نسبت به وثیقه افزایش می‌دهد؛ سود و زیان درصدی روی وثیقه بزرگ‌تر می‌شود. اهرم بالاتر فاصله تا لیکوییدیشن را کم می‌کند. اهرم پیشنهادی در این برنامه صرفاً آموزشی است و تضمین ایمنی نیست."),
        Entry("مارجین ایزوله و کراس", listOf("ایزوله","isolated","کراس","cross","مارجین"), "در ایزوله، وثیقه تخصیص‌یافته به همان پوزیشن محدودتر است. در کراس، موجودی مارجین مشترک می‌تواند برای نگه‌داشت پوزیشن استفاده شود و در عوض بخش بزرگ‌تری از حساب در معرض خطر قرار می‌گیرد. جزئیات دقیق به صرافی و حالت حساب بستگی دارد."),
        Entry("لیکوییدیشن", listOf("لیکویید","liquidation","قیمت لیکویید"), "لیکوییدیشن زمانی رخ می‌دهد که مارجین نگهداری کافی نباشد و صرافی برای کنترل زیان پوزیشن را کاهش یا می‌بندد. قیمت لیکوییدیشن تابع اهرم، مارجین، اندازه پوزیشن، کارمزد، Funding و قواعد صرافی است؛ برآورد ساده جای ماشین‌حساب رسمی صرافی را نمی‌گیرد."),
        Entry("مارک پرایس و لست پرایس", listOf("مارک پرایس","mark price","last price","قیمت مارک"), "Last Price آخرین معامله انجام‌شده است. Mark Price قیمت مرجع محاسبات ریسک و معمولاً لیکوییدیشن است که از شاخص و مبانی بازار مشتق می‌شود. Stop trigger ممکن است بر اساس Mark یا Last تنظیم شود؛ نوع Trigger را باید بررسی کرد."),
        Entry("فاندینگ ریت", listOf("فاندینگ","funding rate","نرخ تامین مالی"), "Funding پرداخت دوره‌ای میان لانگ‌ها و شورت‌ها در قرارداد دائمی است. مثبت بودن معمولاً به معنی پرداخت لانگ به شورت و منفی بودن برعکس است، اما قرارداد و صرافی را بررسی کن. Funding بالا می‌تواند هزینه نگهداری پوزیشن را زیاد کند."),
