    fun answer(question: String): Pair<String, String>? {
        val q = norm(question)
        if (q.length < 3) return null
        val scored = entries.map { entry ->
            val score = entry.keys.sumOf { key ->
                val k = norm(key)
                when {
                    k.isNotBlank() && q.contains(k) -> if (k.contains(' ')) 4 else 3
                    k.length >= 4 && k.split(' ').any { it.length >= 4 && q.contains(it) } -> 1
                    else -> 0
                }
            }
            entry to score
        }.filter { it.second > 0 }.sortedByDescending { it.second }
        val best = scored.firstOrNull() ?: return null
        if (best.second < 3) return null
        val related = scored.drop(1).take(2).map { it.first.title }
        val extra = if (related.isEmpty()) "" else "\n\nموضوعات مرتبط: " + related.joinToString("، ")
        return "دانشنامه گرگ — ${best.first.title}\n\n${best.first.body}$extra\n\nیادآوری: این توضیح آموزشی است؛ قوانین قرارداد و کارمزد را از مستندات رسمی همان صرافی بررسی کن." to "کتابخانه دانشی داخلی گرگ"
    }

    fun entryCount(): Int = entries.size
}
